use anyhow::{bail, Result};

use super::{SCHEMA_V1, SCHEMA_V2, SCHEMA_V3, SCHEMA_V4, SCHEMA_V5, SCHEMA_V6};

pub(super) fn validate_for_schema(path: &str, schema: &str) -> Result<()> {
    validate(path)?;
    if schema == SCHEMA_V1 && path.contains('/') {
        bail!("foreign-process runtime support v1 requires a root file name");
    }
    if !matches!(
        schema,
        SCHEMA_V1 | SCHEMA_V2 | SCHEMA_V3 | SCHEMA_V4 | SCHEMA_V5 | SCHEMA_V6
    ) {
        bail!("foreign-process runtime support path schema is unsupported");
    }
    Ok(())
}

pub(super) fn validate(path: &str) -> Result<()> {
    let components = path.split('/').collect::<Vec<_>>();
    let valid_component = |component: &&str| {
        !component.is_empty()
            && component.len() <= 64
            && !component.starts_with('.')
            && component
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
    };
    let valid = !path.is_empty()
        && path.len() <= 192
        && components.len() <= 8
        && components.iter().all(valid_component)
        && components.first() != Some(&&"capsule.exe");
    if !valid {
        bail!("foreign-process runtime support path must be a bounded relative file path");
    }
    Ok(())
}

pub(super) fn validate_set<'a>(paths: impl Iterator<Item = &'a str>) -> Result<()> {
    let mut keys = paths
        .map(|path| path.to_ascii_lowercase())
        .collect::<Vec<_>>();
    keys.sort();
    let ambiguous = keys
        .windows(2)
        .any(|pair| pair[0] == pair[1] || pair[1].starts_with(&format!("{}/", pair[0])));
    if ambiguous {
        bail!("foreign-process runtime support paths collide during materialization");
    }
    Ok(())
}

